def span(text:str, start:int, end:int) -> dict:
    "A gold span: the characters of `text` from `start` to `end` (exclusive), and those offsets"
    return {"text": text[start:end], "start": int(start), "end": int(end)}

def _splitter():
    from gliner2.processing.word_splitter import WhitespaceTokenSplitter
    return WhitespaceTokenSplitter()

class Words:
    "The words GLiNER2's default splitter reads in a text, to widen a span to the whole words it touches"
    def __init__(self, text:str):
        self.text = text
        ws = [(s, e) for _, s, e in _splitter()(text, lower=False)]
        self.starts, self.ends = [s for s, _ in ws], [e for _, e in ws]
    def __call__(self, start:int, end:int, grow:float=3.0) -> dict|None:
        "The span of the words `start`–`end` touches; None when it touches none, or when they are more than `grow` times longer"
        i, j = bisect.bisect_right(self.ends, start), bisect.bisect_left(self.starts, end) - 1
        if i > j: return None
        s, e = self.starts[i], self.ends[j]
        if e - s > grow * max(1, end - start) and e - s - (end - start) > 4: return None
        return span(self.text, s, e)

