QUOTES = {"``": '"“”«„', "''": '"”“»'}     # the tokens corpora write for quotes, and the characters the text may have
BRACKETS = {"-LRB-": "(", "-RRB-": ")", "-LSB-": "[", "-RSB-": "]", "-LCB-": "{", "-RCB-": "}"}

def token_offsets(tokens:list, text:str, window:int=40) -> list:
    "Each token's (start, end) in `text`, matched left to right ignoring case (`` and '' match a quote); None for one not found within `window` characters"
    out, pos = [], 0
    for t in tokens:
        best = None
        for c in [t, *QUOTES.get(t, ""), *([BRACKETS[t]] if t in BRACKETS else [])]:
            m = re.compile(re.escape(c), re.I).search(text, pos, min(len(text), pos + window + len(c)))
            if m and (best is None or m.start() < best[0]): best = (m.start(), m.end())
        out.append(best)
        if best: pos = best[1]
    return out

