def _span_list(x) -> list:
    "A gold value as a list of spans: a span, a string, or a list of them"
    return list(x) if isinstance(x, list) else [] if x in (None, "") else [x]

def _described(d:dict) -> dict:
    "Descriptions without the empty ones: {name: text}, or for records {record: {field: text}}"
    out = {k: (_described(v) if isinstance(v, dict) else v) for k, v in d.items()}
    return {k: v for k, v in out.items() if v}

def gold_example(row:dict) -> dict:
    "A GLiNER2 training record from a row's ask and gold: spans keep their offsets, what is asked and absent is a negative, a decision's distribution travels beside its labels as soft targets"
    sd = ask_schema(row["ask"]).build(); gold = row.get("gold") or {}
    out, absent, soft = {k: d for k, v in sd.items() if k.endswith("descriptions") and (d := _described(v))}, [], {}
    if sd.get("json_structures"):
        js = []
        for item in sd["json_structures"]:
            (name, fields), = item.items()
            insts = (gold.get("structures") or {}).get(name) or []
            js += [{name: {f: inst.get(f) or "" for f in fields}} for inst in insts] or [{name: {f: "" for f in fields}}]
        out["json_structures"] = js
    if sd.get("entities"):
        ents = gold.get("entities") or {}
        out["entities"] = {t: _span_list(ents.get(t)) for t in sd["entities"]}
    if sd.get("relations"):
        rels = []
        for item in sd["relations"]:
            (name, _), = item.items()
            pairs = (gold.get("relations") or {}).get(name) or []
            rels += [{name: {"head": h, "tail": t}} for h, t in pairs] or [{name: {"head": "", "tail": ""}}]
            if not pairs: absent.append(name)
        out["relations"] = rels
    cls = []
    for c in sd.get("classifications") or []:
        g = (gold.get("classifications") or {}).get(c["task"])
        if g is None: continue                                     # a question without gold teaches nothing
        p = g if isinstance(g, dict) else {l: float(l == g) for l in c["labels"]}
        cls.append({**{k: v for k, v in c.items() if k != "true_label"}, "true_label": [max(c["labels"], key=lambda l: p.get(l, 0.0))]})
        if isinstance(g, dict): soft[c["task"]] = {l: float(p.get(l, 0.0)) for l in c["labels"]}
    if cls: out["classifications"] = cls
    return {"id": row.get("id"), "kind": row.get("kind"), "source": row.get("source"), "input": row["text"], "output": out,
            "absent_relations": absent, "soft": soft, "length": row_length(row)}

def _all_spans(x):
    if isinstance(x, dict) and {"text", "start", "end"} <= x.keys(): yield x
    elif isinstance(x, dict): yield from (s for v in x.values() for s in _all_spans(v))
    elif isinstance(x, list): yield from (s for v in x for s in _all_spans(v))

def spans_ok(e:dict) -> bool:
    "Whether every gold span of a training record is its text's characters at its offsets"
    return all(e["input"][s["start"]:s["end"]] == s["text"] for s in _all_spans(e["output"]))

