def jev_requests(rows) -> list:
    "jev rows (one question each, in stored order) gathered into requests: the questions that share a group and a state, with their targets"
    out, cur, key = [], None, None
    for r in rows:
        k = (r["group_id"], r["state"])
        if k != key:
            if cur: out.append(cur)
            cur, key = {"id": r["group_id"], "state": r["state"], "source": r["source"], "variant": r.get("variant"), "questions": {}, "targets": {}}, k
        cur["questions"][r["question_id"]] = {"type": r["kind"], "instructions": r["question"]} | ({"criteria": list(r["options"])} if len(r["options"]) else {})
        cur["targets"][r["question_id"]] = [float(x) for x in r["target"]]
    return out + ([cur] if cur else [])

def jev_lang(source:str) -> str|None:
    "A jev source's language: the code ending a `multilingual/…` source's name, English otherwise"
    if not source.startswith("multilingual/"): return "en"
    code = source.rsplit("/", 1)[-1]
    return code.split("-", 1)[1] if code.startswith("translation-") else code

def jev_decision_row(req:dict, id:str|None=None, suite:str|None=None) -> dict|None:
    "A row asking every question of a jev request, one GLiNER2 head each, labelled as sysone's GLiNER backend labels typed questions, the targets as soft gold; None when a question cannot be asked"
    from sysone.gliner import gliner_tasks
    try: tasks = gliner_tasks(req["questions"])
    except (ValueError, KeyError, TypeError): return None
    rename = distinct_tasks([t["task"] for t in tasks])
    cls, gold = [], {}
    for t in tasks:
        q, target, names = req["questions"][t["task"]], req["targets"][t["task"]], list(t["names"])
        if len(set(names)) != len(names) or not names: return None
        if q["type"] == "noul":
            if len(target) != 1: return None
            p = {"yes": target[0], "no": 1.0 - target[0]}
        elif len(target) != len(names): return None
        else: p = dict(zip(names, target))
        c = {"task": rename[t["task"]], "labels": names}
        if isinstance(t["labels"], dict) and any(t["labels"].values()): c["label_descriptions"] = {l: d for l, d in t["labels"].items() if d}
        if (t["instruction"] or "").strip(): c["prompt"] = t["instruction"].strip()
        cls.append(c); gold[c["task"]] = p
    row = {"id": id or req["id"], "kind": "decision", "source": req["source"], "lang": jev_lang(req["source"]), "text": req["state"],
           "ask": {"classifications": cls}, "gold": {"classifications": gold}}
    return row | ({"suite": suite} if suite else {})

