def _names(fields:list) -> list:
    "Field names made readable, kept distinct"
    seen, out = Counter(), []
    for f in fields:
        n = _human(f["name"]).lower(); seen[n] += 1
        out.append(n if seen[n] == 1 else f"{n} {seen[n]}")
    return out

def jev_extraction_row(r:dict, suite:str|None=None) -> dict|None:
    "A row from jev's extraction config: list fields as entity types (their instructions as descriptions); a row with a question among its fields as one record, a field per question"
    text, names = r["state"], _names(r["fields"])
    vals = [[span(text, v["start"], v["end"]) for v in (a.get("values") if a.get("values") is not None else [])] if not a.get("null") else []
            for a in r["answers"]]
    if any(text[s["start"]:s["end"]] != s["text"] for v in vals for s in v) or len(vals) != len(names): return None
    if all(f["type"] == "list" for f in r["fields"]):
        ask = {"entities": {n: f["instruction"] for n, f in zip(names, r["fields"])}}
        gold = {"entities": {n: v for n, v in zip(names, vals)}}
    else:
        name = _human(r["source"].split("/")[0]).lower()
        ask = {"structures": {name: {n: {"description": f["instruction"], "dtype": "str" if f["type"] == "text" else "list"} for n, f in zip(names, r["fields"])}}}
        inst = {n: (v[:1] if f["type"] == "text" else v) for n, f, v in zip(names, r["fields"], vals)}  # a question's first gold span; the rest are alternatives
        gold = {"structures": {name: [inst] if any(inst.values()) else []}}
    row = {"id": r["id"], "kind": "extraction", "source": r["source"], "lang": None, "text": text, "ask": ask, "gold": gold}
    return row | ({"suite": suite} if suite else {})

