REDFM_TYPES = {"PER": "person", "ORG": "organization", "LOC": "location", "MISC": "other", "DATE": "date", "TIME": "time", "NUMBER": "number",
               "Concept": "concept"}

def redfm_row(r:dict, source:str, relation_pool:list, rng:random.Random, absent:float=1/3, suite:str|None=None) -> dict|None:
    "A row from RED^FM or SRED^FM: its entities by type and its relations by property name, spans widened to whole words; about `absent` of the relation types asked are ones the text lacks"
    text, w = r["text"], Words(r["text"])
    spans, ents = {}, defaultdict(list)
    for e in r["entities"]:
        b = e.get("boundaries")
        if not b or (s := w(*b)) is None: continue
        spans[tuple(b)] = s
        t = REDFM_TYPES.get(e.get("type"))
        if t and s not in ents[t]: ents[t].append(s)
    rels = defaultdict(list)
    for x in r["relations"]:
        h, t = spans.get(tuple(x["subject"].get("boundaries") or ())), spans.get(tuple(x["object"].get("boundaries") or ()))
        name = ((x.get("predicate") or {}).get("surfaceform") or "").strip().lower()
        if h and t and name and h != t and [h, t] not in rels[name]: rels[name].append([h, t])
    if not rels: return None
    names = sample_types(list(rels), relation_pool, rng, absent)
    types = sample_types(list(ents), list(REDFM_TYPES.values()), rng, absent) if ents else []
    row = {"id": f"{source}/{r.get('docid', '')}", "kind": "extraction", "source": source, "lang": r.get("lan"), "text": text,
           "ask": {"relations": names} | ({"entities": types} if types else {}),
           "gold": {"relations": {n: rels[n] for n in names if n in rels}, "entities": {t: ents[t] for t in types if t in ents}}}
    return row | ({"suite": suite} if suite else {})

DOCRED_TYPES = {"PER": "person", "ORG": "organization", "LOC": "location", "TIME": "time", "NUM": "number", "MISC": "other"}

def joined(sents:list) -> tuple:
    "Tokenized sentences joined by single spaces: the text, and each sentence's tokens' (start, end)"
    parts, offs, pos = [], [], 0
    for sent in sents:
        o = []
        for tok in sent:
            if pos: parts.append(" "); pos += 1
            o.append((pos, pos + len(tok))); parts.append(tok); pos += len(tok)
        offs.append(o)
    return "".join(parts), offs

def windows(lengths:list, most:int) -> list:
    "Consecutive sentences grouped into windows of up to `most` words; a longer sentence is a window of its own"
    out, cur, n = [], [], 0
    for i, k in enumerate(lengths):
        if cur and n + k > most: out.append(cur); cur, n = [], 0
        cur.append(i); n += k
    return out + ([cur] if cur else [])

def _closest(heads:list, tails:list) -> list|None:
    "The head and tail mentions nearest each other: the pair that stands for a relation between two entities with several mentions"
    pairs = [(h, t) for h in heads for t in tails if h != t]
    return list(min(pairs, key=lambda p: abs(p[0]["start"] - p[1]["start"]))) if pairs else None

def _labels(x) -> list:
    "DocRED's relation labels as dicts (h, t, r), from a list of dicts, its string, or the columns of the Hub's loader"
    if isinstance(x, str): x = ast.literal_eval(x)
    if isinstance(x, dict): return [{"h": h, "t": t, "r": r} for h, t, r in zip(x["head"], x["tail"], x["relation_id"])]
    return list(x)

def docred_rows(doc:dict, rel_names:dict, relation_pool:list, rng:random.Random, most:int=250, absent:float=1/3, source:str="re-docred",
                suite:str|None=None) -> list:
    "Rows from a (Re-)DocRED document, a window of sentences each: the mentions by type, and each relation whose entities both have a mention in the window (the nearest two standing for them)"
    vs = ast.literal_eval(doc["vertexSet"]) if isinstance(doc["vertexSet"], str) else doc["vertexSet"]
    sents = list(doc["sents"]); text, offs = joined(sents)
    ment = lambda m: (offs[m["sent_id"]][m["pos"][0]][0], offs[m["sent_id"]][m["pos"][1] - 1][1])
    out = []
    for k, win in enumerate(windows([len(s) for s in sents], most)):
        lo, hi = offs[win[0]][0][0], offs[win[-1]][-1][1]; sub = text[lo:hi]
        inside = [[span(sub, a - lo, b - lo) for m in v if m["sent_id"] in win for a, b in [ment(m)]] for v in vs]
        ents = defaultdict(list)
        for v, ms in zip(vs, inside):
            for s in ms:
                if s not in ents[DOCRED_TYPES.get(v[0]["type"], "other")]: ents[DOCRED_TYPES.get(v[0]["type"], "other")].append(s)
        rels = defaultdict(list)
        for l in _labels(doc["labels"]):
            p = _closest(inside[l["h"]], inside[l["t"]]); name = rel_names.get(l["r"], l["r"])
            if p and p not in rels[name]: rels[name].append(p)
        if not rels: continue
        names, types = sample_types(list(rels), relation_pool, rng, absent), list(ents)
        out.append({"id": f"{source}/{doc.get('title', '')}/{k}", "kind": "extraction", "source": source, "lang": "en", "text": sub,
                    "ask": {"relations": names, "entities": types},
                    "gold": {"relations": {n: rels[n] for n in names if n in rels}, "entities": dict(ents)}} | ({"suite": suite} if suite else {}))
    return out

