EVENT_RELATIONS = {     # MAVEN-ERE's relation types: the name GLiNER2 is asked for, and its description
    "CAUSE": ("causes", "the first event brings about the second"),
    "PRECONDITION": ("is a precondition of", "the first event makes the second possible: without it, the second would not happen"),
    "SUBEVENT": ("has subevent", "the second event is a part of the first"),
    "BEFORE": ("happens before", "the first ends before the second begins"),
    "OVERLAP": ("overlaps in time with", "the two happen partly at the same time"),
    "CONTAINS": ("contains in time", "the second happens within the time of the first"),
    "SIMULTANEOUS": ("happens at the same time as", "the two happen over the same time"),
    "BEGINS-ON": ("begins when", "the two begin at the same time"),
    "ENDS-ON": ("ends when", "the two end at the same time"),
    "COREFERENCE": ("is the same event as", "both mentions refer to one event")}
EVENT_FAMILIES = {"causal": ["CAUSE", "PRECONDITION"], "subevent": ["SUBEVENT"],
                  "temporal": ["BEFORE", "OVERLAP", "CONTAINS", "SIMULTANEOUS", "BEGINS-ON", "ENDS-ON"], "coreference": ["COREFERENCE"]}
EVENT_ENTITIES = {"event": "something that happens or is done, named by the word that says so", "time expression": "a date, time, duration or frequency"}

def relation_families() -> dict:
    "Each relation's family: causal, subevent, temporal or coreference between events; logical between statements (implies, rules out)"
    return {EVENT_RELATIONS[k][0]: f for f, ks in EVENT_FAMILIES.items() for k in ks} | {"implies": "logical", "rules out": "logical"}

def maven_parse(doc:dict) -> tuple:
    "A MAVEN document's text (its sentences joined by spaces), each event's and time expression's mentions as (sentence, span), their types, and the related pairs by MAVEN-ERE type"
    sents = list(doc["sentences"]); text = " ".join(sents)
    base = [0]
    for s in sents[:-1]: base.append(base[-1] + len(s) + 1)
    offs = [[None if o is None else (o[0] + b, o[1] + b) for o in token_offsets(toks, sent)] for b, toks, sent in zip(base, doc["tokens"], sents)]
    def mention(sid, o):
        a, z = offs[sid][o[0]], offs[sid][o[1] - 1]
        return span(text, a[0], z[1]) if a and z and z[1] > a[0] else None
    mentions, types = {}, {}
    for ev in doc.get("events") or []:
        mentions[ev["id"]] = [(m["sent_id"], s) for m in ev["mention"] if (s := mention(m["sent_id"], m["offset"]))]
        types[ev["id"]] = ev["type"]
    for tx in doc.get("TIMEX") or []:
        s = mention(tx["sent_id"], tx["offset"]); mentions[tx["id"]] = [(tx["sent_id"], s)] if s else []
    pairs = defaultdict(list)
    for group in ("temporal_relations", "causal_relations"):
        for k, ps in (doc.get(group) or {}).items(): pairs[k] += [tuple(p) for p in ps]
    pairs["SUBEVENT"] += [tuple(p) for p in doc.get("subevent_relations") or []]
    return text, base, mentions, types, dict(pairs)

def _window_spans(text, base, sents, win, mentions):
    lo, hi = base[win[0]], base[win[-1]] + len(sents[win[-1]])
    sub, ws = text[lo:hi], set(win)
    return sub, {i: [span(sub, s["start"] - lo, s["end"] - lo) for sid, s in ms if sid in ws] for i, ms in mentions.items()}

def maven_ere_rows(doc:dict, most:int=250, per_type:int=16, rng:random.Random|None=None, families:list|None=None, source:str="maven-ere",
                   suite:str|None=None, absent:int|None=None) -> list:
    "Rows from a MAVEN-ERE document, a window of sentences each: its event mentions and time expressions, and the relations of `families` between them with both ends in the window; at most `per_type` pairs of a type. Each row asks every type of `families`, or with `absent` the types its window has and up to `absent` it lacks"
    rng = rng or random.Random(0)
    text, base, mentions, _, pairs = maven_parse(doc)
    asked = {EVENT_RELATIONS[k][0]: EVENT_RELATIONS[k][1] for f in (families or list(EVENT_FAMILIES)) for k in EVENT_FAMILIES[f]}
    out = []
    for n, win in enumerate(windows([len(t) for t in doc["tokens"]], most)):
        sub, inside = _window_spans(text, base, doc["sentences"], win, mentions)
        events = _unique_spans(s for i, ss in inside.items() if i.startswith("EVENT") for s in ss)
        times = _unique_spans(s for i, ss in inside.items() if i.startswith("TIME") for s in ss)
        if not events: continue
        rels = {}
        for k, ps in pairs.items():
            found = [p for a, b in ps if (p := _closest(inside.get(a) or [], inside.get(b) or []))]
            if len(found) > per_type: found = rng.sample(found, per_type)
            if found: rels[EVENT_RELATIONS[k][0]] = found
        coref = [[a, b] for i, ss in inside.items() if i.startswith("EVENT") for a, b in zip(ss, ss[1:])]
        if coref: rels[EVENT_RELATIONS["COREFERENCE"][0]] = coref[:per_type]
        ents = {"event": events} | ({"time expression": times} if times else {})
        names = list(asked)
        if absent is not None:
            lacking = [k for k in asked if k not in rels]
            names = [k for k in asked if k in rels] + rng.sample(lacking, min(absent, len(lacking))); rng.shuffle(names)
        out.append({"id": f"{source}/{doc.get('id', '')}/{n}", "kind": "extraction", "source": source, "lang": "en", "text": sub,
                    "ask": {"entities": {k: EVENT_ENTITIES[k] for k in ents}, "relations": {k: asked[k] for k in names}},
                    "gold": {"entities": ents, "relations": {k: v for k, v in rels.items() if k in names}}} | ({"suite": suite} if suite else {}))
    return out

def _unique_spans(spans) -> list:
    out = []
    for s in spans:
        if s not in out: out.append(s)
    return out

def maven_event_rows(doc:dict, type_pool:list, rng:random.Random, most:int=250, k:int=8, absent:float=1/3, source:str="maven-events",
                     suite:str|None=None) -> list:
    "Rows asking for a MAVEN document's events by type (168 types such as attack, arriving, causation), a window of sentences each: up to `k` of the types it has, and some it lacks"
    text, base, mentions, types, _ = maven_parse(doc)
    out = []
    for n, win in enumerate(windows([len(t) for t in doc["tokens"]], most)):
        sub, inside = _window_spans(text, base, doc["sentences"], win, mentions)
        found = defaultdict(list)
        for i, ss in inside.items():
            if i in types:
                for s in ss:
                    if s not in found[_human(types[i]).lower()]: found[_human(types[i]).lower()].append(s)
        if not found: continue
        asked = sample_types(list(found), type_pool, rng, absent, most=k)
        out.append({"id": f"{source}/{doc.get('id', '')}/{n}", "kind": "extraction", "source": source, "lang": "en", "text": sub,
                    "ask": {"entities": asked}, "gold": {"entities": {t: found[t] for t in asked if t in found}}} | ({"suite": suite} if suite else {}))
    return out

