def sentence_windows(text:str, most:int) -> list:
    "A tokenized text (tokens joined by spaces) cut into windows of whole sentences of up to `most` words: (start, end) offsets"
    ends = [m.end() for m in re.finditer(r" [.!?](?= |$)", text)]
    bounds = [0] + ends + ([len(text)] if not ends or ends[-1] < len(text) else [])
    sents = [(a + (1 if a else 0), b) for a, b in zip(bounds, bounds[1:]) if b > a + 1]
    return [(sents[w[0]][0], sents[w[-1]][1]) for w in windows([len(text[a:b].split()) for a, b in sents], most)]

def event_roles(rows) -> dict:
    "Each MAVEN-Arg event type's argument roles, as the training data uses them"
    roles = defaultdict(set)
    for r in rows:
        for t, insts in r["output"]["json_structures"].items():
            for i in insts: roles[t].update(a["role"] for a in i.get("arguments") or [])
    return {t: sorted(v) for t, v in roles.items()}

def maven_arg_rows(r:dict, roles:dict, rng:random.Random, most:int=250, per_row:int=3, absent:int=1, source:str="maven-arg",
                   suite:str|None=None) -> list:
    "Rows from MAVEN-Arg, a window of sentences each: a record per event (its trigger first, then its arguments by role) for up to `per_row` event types of the window, and `absent` types it lacks"
    text, js = r["input"], r["output"]["json_structures"]
    name = lambda t: _human(t).lower()
    out = []
    for n, (lo, hi) in enumerate(sentence_windows(text, most)):
        sub = text[lo:hi]
        inside = lambda x: lo <= x["start"] and x["end"] <= hi and text[x["start"]:x["end"]] == x["text"]
        recs = defaultdict(list)
        for t, insts in js.items():
            for i in insts:
                if not inside(i["trigger"]): continue
                rec = {"trigger": span(sub, i["trigger"]["start"] - lo, i["trigger"]["end"] - lo)}
                for a in i.get("arguments") or []:
                    if inside(a): rec.setdefault(name(a["role"]), []).append(span(sub, a["start"] - lo, a["end"] - lo))
                recs[t].append(rec)
        if not recs: continue
        present = rng.sample(sorted(recs), min(per_row, len(recs)))
        others = sorted(t for t in roles if t not in recs)
        lacking = rng.sample(others, min(absent, len(others)))
        asked = {name(t): {"trigger": f"the word or phrase that names the {name(t)} event"} | {name(x): "" for x in roles.get(t, [])} for t in present + lacking}
        out.append({"id": f"{source}/{r.get('id', '')}/{n}", "kind": "extraction", "source": source, "lang": "en", "text": sub, "ask": {"structures": asked},
                    "gold": {"structures": {name(t): recs[t] for t in present}}} | ({"suite": suite} if suite else {}))
    return out

