CAUSES = {"causes": EVENT_RELATIONS["CAUSE"][1]}

def unmark(text:str) -> tuple:
    "A text without its <eN>…</eN> marks, and each mark's span in it"
    out, spans, open_, pos = [], {}, {}, 0
    for m in re.finditer(r"<(/?)(e\d+)>", text):
        out.append(text[pos:m.start()]); pos = m.end()
        at = sum(map(len, out))
        if m.group(1): spans[m.group(2)] = (open_.pop(m.group(2), at), at)
        else: open_[m.group(2)] = at
    out.append(text[pos:]); clean = "".join(out)
    return clean, {k: span(clean, a, b) for k, (a, b) in spans.items() if b > a}

def cnc_rows(rows, source:str="causal-news", suite:str|None=None) -> list:
    "Rows from the Causal News Corpus's causal pairs: the text without its marks, each pair (relationship 1: first causes second) a `causes` relation"
    out = []
    for i, r in enumerate(rows):
        text, spans = unmark(r["text"])
        rel = r["relations"]
        rel = [ast.literal_eval(x) for x in re.findall(r"\{[^}]*\}", rel)] if isinstance(rel, str) else list(rel or [])
        pairs = [[spans[x["first"]], spans[x["second"]]] for x in rel if x.get("relationship") == 1 and x["first"] in spans and x["second"] in spans]
        out.append({"id": f"{source}/{i}", "kind": "extraction", "source": source, "lang": "en", "text": text, "ask": {"relations": dict(CAUSES)},
                    "gold": {"relations": {"causes": pairs} if pairs else {}}} | ({"suite": suite} if suite else {}))
    return out

