STATEMENT_RELATIONS = {"implies": "if the first is true, the second is true as well", "rules out": "the two cannot both be true",
                       "causes": EVENT_RELATIONS["CAUSE"][1], "is a precondition of": EVENT_RELATIONS["PRECONDITION"][1]}
SYMMETRIC = {"rules out"}
LIST_STYLES = ("numbered", "dashes", "lines")

def statement_list(statements:list, pairs:list, rng:random.Random, asked:list, source:str, id:str, suite:str|None=None) -> dict:
    "A row listing `statements` in a random order and style, with `pairs` (i, j, relation) between them as gold relations (a symmetric one both ways), asking the relations `asked`"
    order = list(range(len(statements))); rng.shuffle(order)
    style = rng.choice(LIST_STYLES)
    text, spans = "", {}
    for k, i in enumerate(order):
        s = statements[i].strip()
        text += ("\n" if k else "") + {"numbered": f"{k + 1}. ", "dashes": "- ", "lines": ""}[style]
        spans[i] = (len(text), len(text) + len(s.rstrip(".?!;: ")))
        text += s
    rels = defaultdict(list)
    for i, j, r in pairs:
        for a, b in ([(i, j), (j, i)] if r in SYMMETRIC else [(i, j)]):
            p = [span(text, *spans[a]), span(text, *spans[b])]
            if a != b and p not in rels[r]: rels[r].append(p)
    row = {"id": id, "kind": "extraction", "source": source, "lang": "en", "text": text,
           "ask": {"relations": {r: STATEMENT_RELATIONS[r] for r in asked}}, "gold": {"relations": dict(rels)}}
    return row | ({"suite": suite} if suite else {})

def _lists(items:list, rng:random.Random, size:tuple, words:int) -> list:
    "Items shuffled and cut into lists of `size` (low, high) items, each list kept under about `words` words"
    items = list(items); rng.shuffle(items); out = []
    while items:
        cur, n = [], 0
        for _ in range(rng.randint(*size)):
            if not items: break
            k = _words(" ".join(str(x) for x in items[-1]) if isinstance(items[-1], (list, tuple)) else str(items[-1]))
            if cur and n + k > words: break
            cur.append(items.pop()); n += k
        out.append(cur)
    return out

def nli_rows(rows, rng:random.Random, size:tuple=(1, 3), words:int=180, source:str="mnli", suite:str|None=None) -> list:
    "Lists of statements from an NLI dataset (premise, hypothesis, label: 0 entailed, 1 neutral, 2 contradicted): each premise with its hypotheses, the premise implying an entailed one and ruling out a contradicted one"
    groups = defaultdict(list)
    for r in rows:
        if r["label"] in (0, 1, 2) and r["hypothesis"].strip(): groups[r["premise"].strip()].append((r["hypothesis"].strip(), int(r["label"])))
    out = []
    for k, take in enumerate(_lists([[p] + [h for h, _ in hs] for p, hs in groups.items()], rng, size, words)):
        statements, pairs = [], []
        for p, *_ in take:
            if p in statements: continue
            statements.append(p); pi = len(statements) - 1
            for h, label in groups[p]:
                if h in statements: continue
                statements.append(h)
                if label != 1: pairs.append((pi, len(statements) - 1, "implies" if label == 0 else "rules out"))
        out.append(statement_list(statements, pairs, rng, ["implies", "rules out"], source, f"{source}/{k}", suite))
    return out

def copa_rows(rows, rng:random.Random, size:tuple=(2, 3), words:int=180, source:str="e-care", suite:str|None=None) -> list:
    "Lists of statements from cause-and-effect items (premise, question 'cause' or 'effect', choice1, choice2, label 0 or 1): the right choice causes the premise, or the premise causes it; the other choice stands unrelated"
    items = [(r["premise"], r["choice1"], r["choice2"], r["question"], int(r["label"])) for r in rows if r["question"] in ("cause", "effect")]
    out = []
    for k, take in enumerate(_lists(items, rng, size, words)):
        statements, pairs = [], []
        for p, c1, c2, q, label in take:
            b = len(statements); statements += [p, c1, c2]
            pairs.append((b + 1 + label, b, "causes") if q == "cause" else (b, b + 1 + label, "causes"))
        out.append(statement_list(statements, pairs, rng, ["causes"], source, f"{source}/{k}", suite))
    return out

