MARKET_KINDS = ("thresholds", "deadlines", "matches", "elections", "stages", "reach", "counts", "ranges")     # the last held out of training by default

def _money(x, unit:str) -> str:
    v = f"{x:,}" if float(x).is_integer() else f"{x:,.2f}".rstrip("0").rstrip(".")
    return f"{unit}{v}" if unit != "%" else f"{x:.1f}%"

MARKET_SPLIT = 171                 # the salt of the name hash: with it, every pool keeps enough names on both sides

def _part(xs:list, part:str) -> list:
    "The training or the test names of a pool: a name's side follows a hash of it, so a name shared by two pools (a club in a league and a cup) is on the same side of both"
    side = lambda x: zlib.crc32(f"{MARKET_SPLIT}:{x[0] if isinstance(x, tuple) else x}".encode()) % 2 == 0
    return [x for x in xs if side(x) == (part == "train")]

def _market(kind:str, rng:random.Random, w:dict, part:str, used:set):
    "One market group of `kind`: its questions as clauses ('Bitcoin close above $90,000 on June 30, 2025'), and the relations that hold between them; None when its entity is taken"
    if kind == "thresholds":
        (a, unit, levels), d = rng.choice(_part(w["assets"], part)), rng.choice(w["dates"])
        if (a, d) in used or ("reach", a) in used: return None
        used |= {(a, d), ("asset", a)}; xs = sorted(rng.sample(levels, rng.randint(2, min(4, len(levels)))))
        qs = [(x, s) for x in xs for s in ("above", "below") if rng.random() < 0.6] or [(xs[0], "above"), (xs[-1], "above")]
        verb = rng.choice(["close", "be", "trade"])
        clauses = [f"{a} {verb} {s} {_money(x, unit)} on {d}" for x, s in qs]
        pairs = [(i, j, "implies") for i, (x, s) in enumerate(qs) for j, (y, t) in enumerate(qs) if s == t and i != j and (x > y if s == "above" else x < y)]
        pairs += [(i, j, "rules out") for i, (x, s) in enumerate(qs) for j, (y, t) in enumerate(qs) if s == "above" and t == "below" and y <= x]
        return clauses, pairs
    if kind == "deadlines":
        h = rng.choice(_part(w["happenings"], part))
        if h in used: return None
        used.add(h); ds = sorted(rng.sample(range(len(w["dates"])), rng.randint(2, 3)))
        return [f"{h} by {w['dates'][i]}" for i in ds], [(i, j, "implies") for i in range(len(ds)) for j in range(i + 1, len(ds))]
    if kind == "matches":
        name, unit, margins, teams = rng.choice(w["leagues"])
        t1, t2 = rng.sample(_part(teams, part), 2)
        if frozenset((t1, t2)) in used: return None
        used.add(frozenset((t1, t2))); ks = sorted(rng.sample(margins, rng.randint(0, min(2, len(margins)))))
        clauses = [f"{t1} beat {t2} in {name}"] + [f"{t1} beat {t2} by {k} or more {unit} in {name}" for k in ks]
        pairs = [(i, 0, "implies") for i in range(1, len(clauses))] + [(j, i, "implies") for i in range(1, len(clauses)) for j in range(i + 1, len(clauses))]
        if rng.random() < 0.6: clauses.append(f"{t2} beat {t1} in {name}"); pairs.append((0, len(clauses) - 1, "rules out"))
        return clauses, pairs
    if kind == "elections":
        e, people = rng.choice(w["elections"])
        if e in used: return None
        pool = _part(people, part); used.add(e); cs = rng.sample(pool, rng.randint(2, min(3, len(pool))))
        parties = _unique(p for _, p in cs); shown = [p for p in parties if rng.random() < 0.6]
        clauses = [f"{c} win {e}" for c, _ in cs] + [f"the {p} candidate win {e}" for p in shown]
        n = len(cs)
        pairs = [(i, j, "rules out") for i in range(n) for j in range(i + 1, n)]
        pairs += [(i, n + shown.index(p), "implies") for i, (_, p) in enumerate(cs) if p in shown]
        pairs += [(i, n + k, "rules out") for i, (_, p) in enumerate(cs) for k, q in enumerate(shown) if q != p]   # and no other party wins
        pairs += [(n + i, n + j, "rules out") for i in range(len(shown)) for j in range(i + 1, len(shown))]
        return clauses, pairs
    if kind == "stages":
        name, teams, stages = rng.choice(w["tournaments"])
        if name in used: return None
        used.add(name); t = rng.choice(_part(teams, part)); ss = sorted(rng.sample(range(len(stages)), rng.randint(2, min(3, len(stages)))))
        clauses = [f"{t} {stages[s]} {name}" for s in ss]
        pairs = [(j, i, "implies") for i in range(len(ss)) for j in range(i + 1, len(ss))]
        pairs += [(i, j, "is a precondition of") for i in range(len(ss)) for j in range(i + 1, len(ss))]
        if ss[-1] == len(stages) - 1 and rng.random() < 0.5:
            other = rng.choice([x for x in _part(teams, part) if x != t])
            clauses.append(f"{other} {stages[-1]} {name}"); pairs.append((len(ss) - 1, len(clauses) - 1, "rules out"))
        return clauses, pairs
    if kind == "reach":                                 # reaching a price by a date: a higher price, or an earlier date, implies the rest
        a, unit, levels = rng.choice(_part(w["assets"], part))
        if ("asset", a) in used or ("reach", a) in used: return None
        used |= {("asset", a), ("reach", a)}
        xs, ds = sorted(rng.sample(levels, rng.randint(1, min(3, len(levels))))), sorted(rng.sample(range(len(w["dates"])), rng.randint(1, 3)))
        qs = rng.sample([(x, d) for x in xs for d in ds], min(len(xs) * len(ds), rng.randint(2, 4)))
        if len(qs) < 2: return None
        clauses = [f"{a} reach {_money(x, unit)} by {w['dates'][d]}" for x, d in qs]
        return clauses, [(i, j, "implies") for i, (x, d) in enumerate(qs) for j, (y, e) in enumerate(qs) if i != j and y <= x and e >= d]
    if kind == "counts":
        subj, what, levels = rng.choice(_part(w["counts"], part))
        if subj in used: return None
        used.add(subj); ns = sorted(rng.sample(levels, rng.randint(2, min(3, len(levels)))))
        qs = [(x, s) for x in ns for s in ("at least", "fewer than") if rng.random() < 0.6] or [(ns[0], "at least"), (ns[-1], "at least")]
        clauses = [f"{subj} {s} {x:,} {what}" for x, s in qs]
        pairs = [(i, j, "implies") for i, (x, s) in enumerate(qs) for j, (y, t) in enumerate(qs) if s == t and i != j and (x > y if s == "at least" else x < y)]
        pairs += [(i, j, "rules out") for i, (x, s) in enumerate(qs) for j, (y, t) in enumerate(qs) if s == "at least" and t == "fewer than" and y <= x]
        return clauses, pairs
    if kind == "ranges":
        q, unit, lo, step, k, res = rng.choice(_part(w["ranges"], part))
        if q in used: return None
        used.add(q)
        fmt = lambda x: f"{x:.1f}%" if unit == "%" else f"{round(x):,}"
        bounds = [round(lo + i * step, 6) for i in range(k)]
        bs = sorted(rng.sample(range(k - 1), rng.randint(2, min(3, k - 1))))
        clauses = [f"{q} be between {fmt(bounds[i])} and {fmt(bounds[i + 1] - res)}" for i in bs]
        ats = sorted(rng.sample(range(1, k), rng.randint(1, 2)))
        clauses += [f"{q} be at least {fmt(bounds[i])}" for i in ats]
        n = len(bs)
        pairs = [(i, j, "rules out") for i in range(n) for j in range(i + 1, n)]
        pairs += [(i, n + a, "implies") for i, b in enumerate(bs) for a, at in enumerate(ats) if bounds[at] <= bounds[b]]
        pairs += [(i, n + a, "rules out") for i, b in enumerate(bs) for a, at in enumerate(ats) if bounds[at] >= bounds[b + 1]]
        pairs += [(n + a, n + c, "implies") for a, x in enumerate(ats) for c, y in enumerate(ats) if x > y]
        return clauses, pairs
    raise ValueError(f"no market kind {kind!r}")

def market_closure(n:int, pairs:list) -> list:
    "Every relation that follows from `pairs` among `n` questions: implication and precondition through chains, and what implies one of two exclusive questions excluding the other"
    imp = {(a, b) for a, b, r in pairs if r == "implies"}
    pre = {(a, b) for a, b, r in pairs if r == "is a precondition of"}
    for rel in (imp, pre):
        for k in range(n):
            for a in range(n):
                if (a, k) in rel: rel |= {(a, b) for b in range(n) if (k, b) in rel}
    above = lambda x: {x} | {a for a, b in imp if b == x}
    excl = {frozenset((x, y)) for a, b, r in pairs if r == "rules out" for x in above(a) for y in above(b) if x != y}
    return ([(a, b, "implies") for a, b in sorted(imp) if a != b] + [(a, b, "is a precondition of") for a, b in sorted(pre) if a != b]
            + [(*sorted(e), "rules out") for e in sorted(excl, key=sorted)])

def market_rows(n:int, seed:int=0, part:str="train", kinds:tuple=MARKET_KINDS[:-1], world:dict=MARKET_WORLD, source:str="markets",
                suite:str|None=None, fillers:tuple|None=None) -> list:
    "`n` lists of market questions, each from one or two market groups of `kinds` (sometimes two questions joined by 'and') and up to three unrelated questions, every relation that holds marked; `part` picks the training or the test half of the entities, `fillers` the kinds the unrelated questions come from (default: every kind but the last)"
    rng, out = random.Random(f"{seed}:{part}"), []
    while len(out) < n:
        used, clauses, pairs = set(), [], []
        for kind in rng.sample(list(kinds), min(len(kinds), rng.randint(1, 2))):
            if (got := _market(kind, rng, world, part, used)) is None: continue
            b = len(clauses); clauses += got[0]; pairs += [(i + b, j + b, r) for i, j, r in got[1]]
        if not clauses: continue
        for _ in range(rng.randint(0, 3)):
            got = _market(rng.choice(fillers or MARKET_KINDS[:-1]), rng, world, part, used)
            if got: clauses.append(rng.choice(got[0]))
        if len(clauses) >= 2 and rng.random() < 0.3:
            i, j = rng.sample(range(len(clauses)), 2)
            clauses.append(f"{clauses[i]} and {clauses[j]}"); pairs += [(len(clauses) - 1, i, "implies"), (len(clauses) - 1, j, "implies")]
        if len(clauses) > 10: continue
        qs = [f"Will {c}?" for c in clauses]
        asked = ["implies", "rules out", "is a precondition of"]
        out.append(statement_list(qs, market_closure(len(qs), pairs), rng, asked, source, f"{source}-{part}/{len(out)}", suite))
    return out

# %% ../nbs/33_gliner_multitask.ipynb #ef333ac4
def cap(rows:list, most:int, key:str="source", seed:int=0) -> list:
    "At most `most` rows of each `key` value, drawn at random, kept in their order"
    rng, groups = random.Random(seed), defaultdict(list)
    for i, r in enumerate(rows): groups[r.get(key)].append(i)
    keep = sorted(i for ix in groups.values() for i in (ix if len(ix) <= most else rng.sample(ix, most)))
    return [rows[i] for i in keep]

def gliner_words(text:str) -> int:
    "How many words GLiNER2's default splitter reads in `text` (a punctuation mark is a word of its own)"
    return sum(1 for _ in _splitter()(text, lower=False))

def fits(row:dict, words:int=300, tokens:int=700) -> bool:
    "Whether a row is short enough to train on whole: its text up to `words` words as GLiNER2 reads them, its text and ask up to `tokens` tokens"
    return gliner_words(row["text"]) <= words and row_length(row) <= tokens

