def _record(e): return json.loads(e) if isinstance(e, str) else e

SAMPLING = {"synthetic_label_prob": 0.2, "remove_classification_label_prob": 0.2, "include_true_label_prob": 0.8, "remove_relations_prob": 0.0,
            "remove_json_structure_prob": 0.1, "remove_json_field_prob": 0.1, "synthetic_entity_label_prob": 0.1, "swap_head_tail_prob": 0.2}

def set_sampling(processor, sampling:dict|None) -> dict:
    "Change the training-time sampling of a GLiNER2 processor (fields of its `SamplingConfig`); returns the settings now in force"
    cfg = copy.copy(processor.sampling_config)
    for k, v in (sampling or {}).items():
        if not hasattr(cfg, k): raise ValueError(f"GLiNER2's SamplingConfig has no {k!r}")
        setattr(cfg, k, v)
    processor.sampling_config = cfg
    return dict(vars(cfg)) if hasattr(cfg, "__dict__") else {k: getattr(cfg, k) for k in cfg.__dataclass_fields__}

class GoldCollator:
    "GLiNER2 batches from gold training records: GLiNER2's own training-time sampling seeded per batch (or none, for validation), absent relations as negatives, soft decision targets where the labels kept their names; a record the processor refuses is dropped (`drop`) or raises"
    def __init__(self, processor, train:bool=True, max_len:int|None=None, max_gold:int=64, drop:bool=True):
        self.processor, self.train, self.max_len, self.max_gold, self.drop = processor, train, max_len, max_gold, drop
    def _collate(self, examples):
        kw = {"build_targets": True} if "build_targets" in inspect.signature(self.processor._collate_batch).parameters else {}
        return self.processor._collate_batch([(e["input"], json.loads(json.dumps(e["output"]))) for e in examples], max_len=self.max_len,
                                             error_policy="raise", **kw)
    def __call__(self, items:list):
        self.processor.is_training = self.train
        examples = [_record(e) for e, _ in items]
        if self.train: random.seed(items[0][1])
        try: return self._batch(examples)
        except Exception:                                   # a record the processor refuses, at any step: drop it, keep the rest of the batch
            if not self.drop: raise
            ok = []
            for e in examples:
                try: self._batch([e]); ok.append(e)
                except Exception: pass
            if not ok: raise
            if self.train: random.seed(items[0][1])
            return self._batch(ok)
    def _batch(self, examples:list):
        p, batch = self.processor, self._collate(examples)
        for i, e in enumerate(examples):
            absent, soft = set(e.get("absent_relations") or ()), e.get("soft") or {}
            for j, (kind, toks) in enumerate(zip(batch.task_types[i], batch.schema_tokens_list[i])):
                if kind == "relations" and toks[2] in absent: batch.structure_labels[i][j] = [0, []]
                elif kind == "classifications" and soft:
                    probs = soft.get(toks[2]) or next((v for t, v in soft.items() if toks[2].startswith(t + ":")), None)
                    labels = _labels_of(toks)
                    if probs and labels and all(l in probs for l in labels): batch.structure_labels[i][j] = [probs[l] for l in labels]
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            return p._add_boundary_metadata(batch, "boundary", is_training=self.train, build_targets=True, max_gold_per_query=self.max_gold,
                                            on_capacity_exceeded="truncate_with_warning")

# %% ../nbs/33_gliner_multitask.ipynb #b303696d
def adapter_model(model, r:int=64, alpha:float|None=None, heads:bool=True):
    "A LoRA adapter over a GLiNER2 model: rank `r` on the encoder's linear layers (their bias changes inside the adapter, so switching it off gives the model back), the heads trained whole"
    from peft import LoraConfig, get_peft_model
    keep = [n for n, _ in model.named_children() if n != "encoder"] if heads else None
    return get_peft_model(model, LoraConfig(r=r, lora_alpha=alpha or r, target_modules=lora_targets(model), lora_dropout=0.0, bias="none",
                                            lora_bias=True, modules_to_save=keep))

class GlinerLearner(DistillLearner):
    "Train a GLiNER2 model on gold records, whole or as an adapter: GLiNER2's training-time sampling, soft decision targets, a loss per task"
    def __init__(self, model, train:list, valid:list|None=None, bs:int=16, lr:float=1e-5, head_lr:float=5e-4, lora_lr:float=2e-4,
                 weight_decay:float=0.01, weights:dict|None=None, balance:bool=False, sampling:dict|None=SAMPLING, max_len:int|None=384, max_tokens:int|None=4096,
                 warmup:float=0.06, seed:int=0, precision:str="auto", workers:int=0, log_every:int=25, verbose:bool=True, device=None):
        super().__init__(model, [], [], bs=bs, lr=lora_lr, full_lr=head_lr, max_len=max_len, max_tokens=max_tokens, warmup=warmup, seed=seed,
                         precision=precision, workers=workers, log_every=log_every, verbose=verbose, device=device)
        self.train, self.valid = list(train), list(valid or [])
        if not hasattr(model, "peft_config"):
            for p in model.parameters(): p.requires_grad_(True)
        self.enc_lr, self.head_lr, self.lora_lr, self.weight_decay, self.balance = lr, head_lr, lora_lr, weight_decay, balance
        self.weights = {"decision": 1.0, "span": 1.0, "relation": 1.0} | dict(weights or {})
        self.lengths = [_length(e) for e in self.train]; self.valid_lengths = [_length(e) for e in self.valid]
        self.kinds = Counter(_record(e).get("kind") for e in self.train) if len(self.train) < 50_000 else None
        m = _unwrap(model); g = m.boundary_settings.max_gold_per_query
        self.sampling = set_sampling(m.processor, sampling)
        self.collate, self.valid_collate = GoldCollator(m.processor, True, max_len, g), GoldCollator(m.processor, False, max_len, g)
        self.state["scales"] = {}
    def __repr__(self):
        return f"GlinerLearner({len(self.train):,} train · {len(self.valid):,} valid · {'adapter' if hasattr(self.model, 'peft_config') else 'full'} · bs {self.bs} · {self.precision} · {self.device})"

def _length(e) -> int:
    e = _record(e)
    return e.get("length") or row_length({"text": e["input"], "ask": {}}) + 50

# %% ../nbs/33_gliner_multitask.ipynb #20129e69
def _group(name:str) -> str:
    "Which learning rate a parameter takes: an adapter's matrices, the encoder, or the heads"
    return "lora" if "lora_" in name else "encoder" if name.startswith("encoder.") or ".encoder." in name else "heads"

@patch
def _setup(self:GlinerLearner, epochs:int):
    "AdamW over three groups (the adapter's matrices, the encoder, the heads), decay on weight matrices only; warmup, then a cosine decay to zero"
    self.model.to(self.device)
    lrs = {"lora": self.lora_lr, "encoder": self.enc_lr, "heads": self.head_lr}
    groups = defaultdict(list)
    for n, p in self.trainable(): groups[(_group(n), p.ndim >= 2 and "embeddings" not in n)].append(p)
    self.opt = torch.optim.AdamW([{"params": ps, "lr": lrs[g], "weight_decay": self.weight_decay if decay else 0.0} for (g, decay), ps in groups.items()])
    self.batches = [epoch_batches(self.train, self.bs, self.seed, e, max_tokens=self.max_tokens, lengths=self.lengths) for e in range(epochs)]
    total = sum(len(b) for b in self.batches); warm = max(1, int(self.warmup * total))
    f = lambda s: (s + 1) / warm if s < warm else 0.5 * (1 + math.cos(math.pi * min(1.0, (s - warm) / max(1, total - warm))))
    self.sched = torch.optim.lr_scheduler.LambdaLR(self.opt, f)
    self.state["epochs"], self.state["max_steps"] = epochs, total

@patch
def _loader(self:GlinerLearner, examples:list, batches:list, collate=None):
    "A DataLoader over `batches` of `examples`, each batch carrying its seed (the run's seed, the epoch and the batch's first records)"
    ep = self.state["epoch"]
    items = [(examples[i], zlib.crc32(f"{self.seed}:{ep}:{':'.join(map(str, b[:4]))}".encode())) for b in batches for i in b]
    return DataLoader(items, batch_sampler=_Offsets(batches), collate_fn=collate or self.collate, num_workers=self.workers,
                      generator=torch.Generator().manual_seed(self.seed))

@patch
def _parts(self:GlinerLearner, batch) -> dict:
    "The step's losses by head: decisions, relations, and the spans of entities and records (the rest of GLiNER2's loss)"
    batch = batch.to(self.device)
    with torch.autocast(self.device.type, dtype=torch.bfloat16, enabled=self.precision == "bf16"):
        out = self.model(batch)
    L, zero = out.losses or {}, torch.zeros((), device=self.device)
    dec = L["classification_loss"].float() if L.get("classification_loss") is not None else zero
    rel = L["relation_loss"].float() if L.get("relation_loss") is not None else zero
    return {"decision": dec, "relation": rel, "span": out.loss.float() - dec - rel if out.loss is not None else zero}

@patch
def _combine(self:GlinerLearner, parts:dict) -> torch.Tensor:
    "The weighted sum of the losses; with `balance`, each first divided by its running average (kept with the checkpoint)"
    if not self.balance: return sum(self.weights.get(k, 1.0) * v for k, v in parts.items())
    sc, total = self.state["scales"], 0.0
    for k, v in parts.items():
        x = float(v.detach())
        if x > 0 and self.model.training: sc[k] = 0.98 * sc[k] + 0.02 * x if k in sc else x
        total = total + self.weights.get(k, 1.0) * v / max(sc.get(k, 1.0), 1e-6)
    return total

@patch
def validate(self:GlinerLearner) -> dict:
    "Mean losses by head over the validation records, without sampling or dropout; a head's mean over the batches that train it"
    if not self.valid: return {}
    m = _unwrap(self.model)
    rng = (random.getstate(), torch.get_rng_state(), torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None)
    self.model.eval(); m.training = True              # the top module only: GLiNER2 computes the relation loss, dropout and sampling stay off
    sums, counts = defaultdict(float), defaultdict(int)
    try:
        with torch.no_grad():
            for batch in self._loader(self.valid, epoch_batches(self.valid, self.bs, self.seed, 0, max_tokens=self.max_tokens, lengths=self.valid_lengths),
                                      self.valid_collate):
                for name, v in self._parts(batch).items():
                    if float(v) != 0: sums[name] += float(v); counts[name] += 1
    finally:
        m.training = False; self.model.train()
        random.setstate(rng[0]); torch.set_rng_state(rng[1])
        if rng[2] is not None: torch.cuda.set_rng_state_all(rng[2])
    return {f"valid_{k}": sums[k] / counts[k] for k in sums}

@patch
def _load(self:GlinerLearner, path):
    "Continue from a checkpoint, the losses' running averages included"
    DistillLearner._load(self, path)
    self.state["scales"] = json.loads((Path(path) / "sysone_state.json").read_text()).get("scales") or {}

