def gold_record(learn:GlinerLearner, **extra) -> dict:
    "What trained a model: the code, the environment and hardware, the run's settings, the time it took and its log; plus `extra` (data, scores)"
    from sysone.record import environment, hardware, git_info, entry_point
    import sysone, datetime, os
    shipped = json.loads(os.environ.get("SYSONE_SOURCE") or "{}")
    return {"recorded": datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds"),
            "code": {"git": git_info() or shipped.get("git"), "sysone": sysone.__version__, "entry": entry_point()},
            "environment": environment(), "hardware": hardware(), "job": json.loads(os.environ.get("SYSONE_JOB") or "null"),
            "training": {"kind": "adapter" if hasattr(learn.model, "peft_config") else "full", "epochs": learn.state.get("epochs"),
                         "steps": learn.state["step"], "bs": learn.bs, "lr": learn.enc_lr, "head_lr": learn.head_lr, "lora_lr": learn.lora_lr,
                         "weight_decay": learn.weight_decay, "weights": learn.weights, "balance": learn.balance, "sampling": learn.sampling,
                         "precision": learn.precision,
                         "seed": learn.seed, "max_tokens": learn.max_tokens, "max_len": learn.max_len, "seconds": round(learn.state["seconds"], 1),
                         "train": len(learn.train), "valid": len(learn.valid), "trainable": sum(p.numel() for _, p in learn.trainable()),
                         "resumed_from_step": learn.state.get("resumed_from_step"), "log": learn.log}} | extra

def export_model(model, path, base:str=BASE, record:dict|None=None, name:str|None=None) -> Path:
    "The trained model in `path`: a GLiNER2 checkpoint, or an adapter in PEFT's format; `sysone_gliner.json` gives its name and the model it was trained from, `training.json` how"
    path = Path(path); path.mkdir(parents=True, exist_ok=True)
    adapter = hasattr(model, "peft_config")
    with warnings.catch_warnings():               # PEFT takes the adapter's 1-D bias vectors (lora_B.bias) for unsharded ZeRO-3 tensors; they are whole
        warnings.filterwarnings("ignore", message=r".*LoRA tensor\(s\) have invalid shape.*")
        (model if adapter else _unwrap(model)).save_pretrained(str(path))
    (path / "sysone_gliner.json").write_text(json.dumps({"backend": "gliner2", "base": base, "adapter": adapter, "regime": "multitask gold labels",
                                                          "temperature": {}, "name": name or path.name}, indent=2))
    if record is not None: (path / "training.json").write_text(json.dumps(record, indent=1, default=str))
    return path

