def _md_table(rows:list, cols:list) -> str:
    return "\n".join(["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)] + ["| " + " | ".join(map(str, r)) + " |" for r in rows])

def model_card(path, repo_id:str, base:str=BASE, scores:dict|None=None, limitations:list|None=None, data_repo:str|None=None,
               description:str|None=None, thresholds:dict|None=None, license:str="other", scores_note:str|None=None) -> str:
    "README.md for an export of `GlinerLearner` (an adapter or a whole model): what it does, how to load and ask it, its `scores` ({model: {column: value}}), limitations, data and training"
    path = Path(path); rec = json.loads((path / "training.json").read_text()) if (path / "training.json").exists() else {}
    tr, data = rec.get("training") or {}, rec.get("data") or {}
    adapter = (path / "adapter_config.json").exists()
    rank = json.loads((path / "adapter_config.json").read_text()).get("r") if adapter else None
    th = thresholds or {"entities": 0.5, "relations": 0.3, "structures": 0.3}
    name = repo_id.split("/")[-1]
    load = (f'model = PeftModel.from_pretrained(AutoExtractor.from_pretrained("{base}"), "{repo_id}").get_base_model()' if adapter
            else f'model = AutoExtractor.from_pretrained("{repo_id}")')
    front = ["---", f"license: {license}", f"base_model: {base}", *(["library_name: peft"] if adapter else []), "pipeline_tag: schema-extraction",
             "tags:", *[f"- {t}" for t in ("gliner2", *(("lora",) if adapter else ()), "information-extraction", "relation-extraction", "event-extraction",
                                          "causal-relations", "decision-model", "sysone")],
             "language:", "- en", "---", ""]
    body = [f"# {name}", "",
            description or (f"[{base}](https://huggingface.co/{base}) trained further on gold labels from public datasets, "
                            + ("as a LoRA adapter, " if adapter else "") + "to make decisions of every kind, find entities of any type, and relate them: "
                            "entity to entity, event to event (causes, is a precondition of, happens before, has subevent), and statement to statement "
                            "(implies, rules out). Trained with [sysonelib](https://github.com/sgaseretto/sysonelib)'s `sysone.multitask`."), "",
            "## Use it", "", "```python", "from gliner2 import AutoExtractor", *(["from peft import PeftModel"] if adapter else []), "", load, "",
            'model.classify_text("My card was charged twice", {"intent": ["billing", "shipping", "account"]})',
            f'model.extract_entities("Ana Ruiz joined Acme in Madrid", ["person", "company", "city"], threshold={th["entities"]})',
            'model.extract_relations("1. Will Bitcoin close above $100,000 on June 30?\\n2. Will Bitcoin close above $90,000 on June 30?",',
            '                        {"implies": "if the first is true, the second is true as well",',
            '                         "rules out": "the two cannot both be true"},' + f" threshold={th['relations']})", "```", "",
            f"It finds relations more cautiously than entities: entities read best at a threshold of {th['entities']}, relations and record fields at "
            f"{th['relations']}. To relate many statements (markets, claims, events), sysone's `statement_graph` reads them a few blocks at a time so "
            "that every two share a list.", ""]
    if adapter:
        body += [f"The adapter is not merged: the base's weights stay as they are. It adds rank-{rank} changes, with their biases, to the encoder's linear "
                 "layers, and carries its own copies of the heads (decisions, spans, records, relations); switched off, it gives the base back. "
                 "PEFT's `merge_and_unload()` folds it into the weights.", ""]
    if scores:
        cols = list(dict.fromkeys(c for v in scores.values() for c in v))
        body += ["## Scores", "", "On held-out test suites: accuracy for decisions, strict F1 (exactly the gold's words) for entities, records and relations."
                 + (f" {scores_note}" if scores_note else ""), "",
                 _md_table([[m] + [("" if v.get(c) is None else f"{v[c]:.3f}") for c in cols] for m, v in scores.items()], ["model", *cols]), ""]
    if limitations: body += ["## Limitations", ""] + [f"- {x}" for x in limitations] + [""]
    if data:
        body += ["## Data", "", f"Training records from {len(data.get('train') or {})} datasets, with their gold labels" + (f", stored as [{data_repo}](https://huggingface.co/datasets/{data_repo})" if data_repo else "")
                 + ". Each source's own terms apply to what came from it; some (GPL-3.0, CC BY-SA 4.0) ask that derived work share alike, hence `license: other`.", "",
                 _md_table(sorted(((k, f"{v:,}") for k, v in (data.get("train") or {}).items()), key=lambda r: -int(r[1].replace(",", ""))), ["dataset", "training records"]), ""]
        srcs = data.get("sources") or {}
        if srcs: body += [_md_table([(k, v.get("repo", ""), v.get("license", "")) for k, v in srcs.items()], ["source", "from", "terms"]), ""]
    if tr:
        gpu = ", ".join(((rec.get("hardware") or {}).get("accelerator") or {}).get("devices") or ["?"])
        body += ["## Training", "",
                 f"- {'A LoRA adapter, rank ' + str(rank) if adapter else 'Every weight'}; {tr.get('trainable', 0):,} trainable numbers",
                 f"- {tr.get('train', 0):,} training records, {tr.get('epochs')} epochs, {tr.get('steps', 0):,} steps of up to {tr.get('bs')} records and "
                 f"{tr.get('max_tokens')} padded tokens; {tr.get('precision')}",
                 f"- Learning rates: {tr.get('lora_lr') if adapter else tr.get('lr')} ({'LoRA' if adapter else 'encoder'}), {tr.get('head_lr')} (heads); AdamW, "
                 f"weight decay {tr.get('weight_decay')}, warmup then cosine decay",
                 f"- Loss: GLiNER2's per-head losses (decisions, relations, spans)"
                 + (", each divided by its running average" if tr.get("balance") else "") + ", weighted " + ", ".join(f"{k} {v:g}" for k, v in (tr.get("weights") or {}).items()),
                 f"- {tr.get('seconds', 0) / 60:.0f} minutes on {gpu}", ""]
    (path / "README.md").write_text("\n".join(front + body))
    return "\n".join(front + body)

def push_model(path, repo_id:str, private:bool=True, replace:bool=False, commit_message:str|None=None, token=None, **card_kw) -> dict:
    "Write the card and upload an export of `GlinerLearner` to a Hub model repo, private by default; with `replace`, files the folder lacks are removed from the repo"
    from huggingface_hub import HfApi
    model_card(path, repo_id, **card_kw)
    api = HfApi(token=token)
    api.create_repo(repo_id, private=private, exist_ok=True)
    info = api.upload_folder(repo_id=repo_id, folder_path=str(path), commit_message=commit_message or "Model, card and training record",
                             delete_patterns="*" if replace else None)
    return {"repo": repo_id, "private": private, "commit": info.oid, "url": info.commit_url}

