def gold_data_card(path, repo_id:str, title:str|None=None, built_by:str|None=None) -> Path:
    "Write README.md, a dataset card, for a built gold mix in `path`, from its data.json: files, the mix, the test suites, the sources and their terms, the record format, and how to read it"
    path = Path(path); d = json.loads((path / "data.json").read_text())
    files = sorted(str(p.relative_to(path)) for p in path.rglob("*") if p.is_file() and p.name != "README.md")
    mb = lambda f: (lambda n: f"{n / 1e6:.1f} MB" if n >= 1e5 else f"{max(1, round(n / 1e3))} KB")((path / f).stat().st_size)
    table = lambda rows, cols: "\n".join(["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)] + ["| " + " | ".join(map(str, r)) + " |" for r in rows])
    sources = d.get("sources") or {}
    out = ["---", "license: other", f"pretty_name: {title or repo_id.split('/')[-1]}", "viewer: false",
           "task_categories:", "- token-classification", "- text-classification", "- zero-shot-classification",
           "tags:", "- gliner2", "- information-extraction", "- relation-extraction", "- event-relations", "- sysone", "---", "",
           f"# {title or repo_id.split('/')[-1]}", "",
           f"GLiNER2 training records with gold labels for decisions, entities and relations (between entities, events and statements), "
           f"{d.get('train_rows', 0):,} for training and {d.get('valid_rows', 0):,} for validation, and {sum((d.get('eval') or {}).values()):,} test rows "
           f"in {len(d.get('eval') or {})} suites, built with [sysone](https://github.com/sgaseretto/sysonelib)'s `sysone.multitask` readers"
           + (f" by {built_by}" if built_by else "") + ".", "",
           "## Files", "", table([(f"`{f}`", mb(f)) for f in files], ["file", "size"]), "",
           "A copy on Kaggle holds the same files, the `.gz` ones decompressed (Kaggle unpacks them).", "",
           "## The training mix", "", table(sorted(((k, f"{v:,}") for k, v in (d.get("train") or {}).items()), key=lambda r: -int(r[1].replace(",", ""))),
                                           ["dataset", "records"]), "",
           f"Dropped before training: {(d.get('dropped') or {}).get('exact', 0):,} rows whose text is a test row's, {(d.get('dropped') or {}).get('near', 0):,} near duplicates "
           f"of one (MinHash, Jaccard ≥ 0.6), and the records GLiNER2's processor refused: {', '.join(f'{k} ({v:,})' for k, v in ((d.get('dropped') or {}).get('refused') or {}).items()) or 'none'}.", "",
           "## Test suites", "", table([(k, f"{v:,}") for k, v in (d.get("eval") or {}).items()], ["suite", "rows"]), "",
           "`eval/rows.jsonl` holds them with their gold; `eval/answers/` and `scores.json`, the answers and scores of the models the build scored.", "",
           "## Sources and terms", "", "The mix gathers sources under different terms; each source's own terms apply to what comes from it.", "",
           table([(k, v.get("repo", ""), v.get("license", "")) for k, v in sources.items()], ["source", "from", "terms"]), "",
           "## Format", "",
           "One JSON object a line. A training record is GLiNER2's: `input` (the text) and `output` (what to find, with the gold), each gold span "
           "`{\"text\", \"start\", \"end\"}` in characters of the text; a relation or type asked with nothing found is a negative. Beside them: "
           "`absent_relations` (relation types asked and absent), `soft` (a decision's gold distribution, when annotators disagreed), `length` "
           "(a rough token count), and `id`, `kind`, `source`, `dataset`.", "",
           "## Reading it", "", "```python", "import gzip, json", "from huggingface_hub import snapshot_download", "",
           f'folder = snapshot_download("{repo_id}", repo_type="dataset")',
           'train = [json.loads(l) for l in gzip.open(f"{folder}/train.jsonl.gz", "rt")]', "```", "",
           "sysone's `GlinerLearner` trains on these lines as they are (`sysone.multitask`)."]
    (path / "README.md").write_text("\n".join(out) + "\n")
    return path / "README.md"

