def _text(x) -> str: return x["text"] if isinstance(x, dict) else str(x)

def _found(ask:dict, res:dict) -> dict:
    "A batch_extract result as {entities, relations, structures}, each span [text, confidence, start, end]"
    sp = lambda x: [x.get("text"), round(float(x.get("confidence", 1.0)), 4), x.get("start"), x.get("end")]
    many = lambda v: [sp(x) for x in (v if isinstance(v, list) else [v]) if isinstance(x, dict) and x.get("text")]
    out = {}
    if ask.get("entities"): out["entities"] = {t: many((res.get("entities") or {}).get(t) or []) for t in ask["entities"]}
    if ask.get("relations"):
        rel = res.get("relation_extraction") or {}
        out["relations"] = {n: [sp(p["head"])[:1] + sp(p["tail"])[:1] + [round(float(p.get("confidence", min(p["head"].get("confidence", 1), p["tail"].get("confidence", 1)))), 4)]
                                for p in rel.get(n) or [] if isinstance(p, dict) and p.get("head") and p.get("tail")] for n in ask["relations"]}
    if ask.get("structures"):
        out["structures"] = {n: [{f: many(inst.get(f) or []) for f in fields} for inst in res.get(n) or [] if isinstance(inst, dict)]
                             for n, fields in ask["structures"].items()}
    return out

def answers(model, rows:list, batch_size:int=8, threshold:float=0.5, max_tokens:int|None=8192, thresholds:dict|None=None) -> list:
    "What `model` answers to each row: entities, relations and record fields with confidences and offsets, and each decision's logits; `thresholds` ({'entities': .., 'relations': .., 'structures': ..}) overrides `threshold` for a kind"
    m = _unwrap(model).eval(); out = [{} for _ in rows]
    ext = [i for i, r in enumerate(rows) if any(r["ask"].get(k) for k in ("entities", "relations", "structures"))]
    with torch.inference_mode():
        for b in length_batches([row_length(rows[i]) for i in ext], batch_size, max_tokens):
            chunk = [ext[k] for k in b]
            res = m.batch_extract([rows[i]["text"] for i in chunk], [ask_schema(rows[i]["ask"], thresholds) for i in chunk], batch_size=len(chunk),
                                  threshold=threshold, include_confidence=True, include_spans=True)
            for i, x in zip(chunk, res): out[i] = _found(rows[i]["ask"], x)
    dec = [i for i, r in enumerate(rows) if r["ask"].get("classifications")]
    for i, lg in zip(dec, decision_logits(m, [rows[i] for i in dec], batch_size, max_tokens)): out[i]["logits"] = lg
    return out

