def _items(kind:str, d:dict, gold:bool) -> set:
    "A row's gold or answers of one kind as a set of (label, text, …), texts normalised"
    if kind == "entities":
        return {(t, _norm(_text(x if gold else x[0]))) for t, xs in (d.get("entities") or {}).items() for x in (_span_list(xs) if gold else xs)}
    if kind == "relations":
        return {(n, _norm(_text(p[0])), _norm(_text(p[1]))) for n, ps in (d.get("relations") or {}).items() for p in ps}
    return {((n, f), _norm(_text(x if gold else x[0]))) for n, insts in (d.get("structures") or {}).items() for i in insts
            for f, xs in i.items() for x in (_span_list(xs) if gold else xs)}

def _close(a:str, b:str) -> bool: return a == b or (len(a) > 0 and len(b) > 0 and (a in b or b in a))

def _hits(pred:set, gold:set, relaxed:bool) -> int:
    "How many answers match a gold item: the same label and texts, or (relaxed) texts that contain one another; each gold item matched once"
    if not relaxed: return len(pred & gold)
    used, tp = set(), len(pred & gold)
    used |= pred & gold
    for p in pred - gold:
        g = next((g for g in gold - used if g[0] == p[0] and all(_close(x, y) for x, y in zip(p[1:], g[1:]))), None)
        if g is not None: used.add(g); tp += 1
    return tp

KINDS = {"entities": "entities", "relations": "relations", "records": "structures"}

def row_counts(pred:dict, row:dict, families:dict|None=None) -> dict:
    "One row's counts: decisions (right, asked, confidence) and, per kind of span and per relation family, (hits, answers, gold), strict and relaxed"
    out, gold, ask = {}, row.get("gold") or {}, row["ask"]
    for task, lg in (pred.get("logits") or {}).items():
        g = (gold.get("classifications") or {}).get(task)
        if g is None: continue
        g = max(g, key=g.get) if isinstance(g, dict) else g
        labels = list(lg); p = _softmax([lg[l] for l in labels])
        out.setdefault("decisions", []).append((labels[int(p.argmax())] == g, float(p.max())))
    for kind, key in KINDS.items():
        if not ask.get(key): continue
        P, G = _items(kind, pred, False), _items(kind, gold, True)
        groups = {kind: (P, G)}
        if kind == "relations" and families:
            for f in _unique(families.get(n) for n in ask["relations"] if families.get(n)):
                groups[f"relations:{f}"] = ({x for x in P if families.get(x[0]) == f}, {x for x in G if families.get(x[0]) == f})
        for name, (p, g) in groups.items():
            for relaxed in (False, True): out[name + ("~" if relaxed else "")] = (_hits(p, g, relaxed), len(p), len(g))
    return out

def _boot(stat, arr:np.ndarray, n:int, seed:int) -> list:
    "A 95% interval for `stat` from resampling the rows of `arr` `n` times; resamples where it is undefined are left out"
    rng = np.random.default_rng(seed)
    vals = np.array([stat(arr[rng.integers(0, len(arr), len(arr))]) for _ in range(n)], float)
    vals = vals[np.isfinite(vals)]
    return [round(float(np.percentile(vals, 2.5)), 4), round(float(np.percentile(vals, 97.5)), 4)] if len(vals) else [float("nan")] * 2

def _prf(c) -> tuple:
    tp, npred, ngold = map(float, c)
    p, r = (tp / npred if npred else float("nan")), (tp / ngold if ngold else float("nan"))
    return p, r, float(_f1(tp, npred - tp, ngold - tp))

def gold_scores(pred:list, rows:list, by:str="suite", families:dict|None=None, boot:int=1000, seed:int=0) -> dict:
    "Scores against the gold per suite (the rows' `by`): decision accuracy and calibration, span precision, recall and F1 (strict, and relaxed with `~`), with 95% bootstrap intervals over rows"
    counts = [row_counts(p, r, families) for p, r in zip(pred, rows)]
    groups = defaultdict(list)
    for i, r in enumerate(rows): groups[r.get(by) or r.get("source")].append(i)
    out = {}
    for g, ix in groups.items():
        s = {"rows": len(ix)}
        dec = [(i, x) for i in ix for x in counts[i].get("decisions", [])]
        if dec:
            right = np.array([x[0] for _, x in dec], float); conf = [x[1] for _, x in dec]
            per = np.array([[sum(x[0] for x in counts[i].get("decisions", [])), len(counts[i].get("decisions", []))] for i in ix], float)
            s |= {"decisions": len(dec), "accuracy": float(right.mean()), "accuracy_ci": _boot(lambda a: a[:, 0].sum() / max(1, a[:, 1].sum()), per, boot, seed),
                  "ece": ece(conf, right)}
        for name in _unique(k for i in ix for k in counts[i] if k != "decisions"):
            per = np.array([counts[i].get(name, (0, 0, 0)) for i in ix], float)
            p, r, f = _prf(per.sum(0))
            s |= {f"{name}_p": p, f"{name}_r": r, f"{name}_f1": f, f"{name}_n": int(per[:, 2].sum())}
            if not name.endswith("~"): s[f"{name}_f1_ci"] = _boot(lambda a: _prf(a.sum(0))[2], per, boot, seed)
        out[g] = s
    return out

