def cover(n:int, block:int) -> list:
    "Lists of indices in which every pair of `n` items shares a list: the items cut into blocks of `block`, every two blocks read together"
    blocks = [list(range(s, min(s + block, n))) for s in range(0, n, block)]
    return [a + b for k, a in enumerate(blocks) for b in blocks[k + 1:]] or blocks[:1]

def statement_graph(model, statements:list, relations:dict|None=None, block:int=8, threshold:float=0.5, batch_size:int=8) -> list:
    "The relations among `statements` as edges (i, j, relation, confidence), read a few blocks at a time (`cover`), each list numbered as in training; an edge seen in several lists keeps its highest confidence"
    rel = relations or STATEMENT_RELATIONS
    rows, where = [], []
    for g in cover(len(statements), block):
        text, spans = "", []
        for k, i in enumerate(g):
            text += ("\n" if k else "") + f"{k + 1}. "
            s = statements[i].strip(); spans.append((len(text), len(text) + len(s), i)); text += s
        rows.append({"text": text, "ask": {"relations": rel}}); where.append(spans)
    m, edges = _unwrap(model).eval(), {}
    def at(spans, x):
        mid = (x["start"] + x["end"]) / 2 if x.get("start") is not None else None
        return next((i for s, e, i in spans if mid is not None and s <= mid < e), None)
    with torch.inference_mode():
        for b in length_batches([row_length(r) for r in rows], batch_size, 8192):
            res = m.batch_extract([rows[k]["text"] for k in b], [ask_schema(rows[k]["ask"]) for k in b], batch_size=len(b), threshold=threshold,
                                  include_confidence=True, include_spans=True)
            for k, x in zip(b, res):
                for name, ps in (x.get("relation_extraction") or {}).items():
                    for p in ps or []:
                        if not (isinstance(p, dict) and p.get("head") and p.get("tail")): continue
                        h, t = at(where[k], p["head"]), at(where[k], p["tail"])
                        if h is None or t is None or h == t: continue
                        c = float(p.get("confidence", min(p["head"].get("confidence", 1), p["tail"].get("confidence", 1))))
                        edges[(h, t, name)] = max(edges.get((h, t, name), 0.0), c)
    return sorted([(h, t, r, round(c, 4)) for (h, t, r), c in edges.items()], key=lambda e: (-e[3], e[:3]))

