def market_pool(groups:int, seed:int=0, part:str="test", kinds:tuple=MARKET_KINDS[:-1], world:dict=MARKET_WORLD) -> tuple:
    "Questions from up to `groups` market groups that share no entity, shuffled, and every relation among them as (i, j, relation), a symmetric one both ways"
    rng, used, clauses, pairs, made = random.Random(f"pool:{seed}:{part}"), set(), [], [], 0
    for _ in range(groups * 5):                         # a draw whose entity is taken is skipped; stop at `groups` groups
        if (got := _market(rng.choice(list(kinds)), rng, world, part, used)) is None: continue
        b = len(clauses); clauses += got[0]; pairs += [(i + b, j + b, r) for i, j, r in got[1]]; made += 1
        if made == groups: break
    order = list(range(len(clauses))); rng.shuffle(order); place = {i: k for k, i in enumerate(order)}
    gold = {(place[i], place[j], r) for i, j, r in market_closure(len(clauses), pairs)}
    gold |= {(j, i, r) for i, j, r in gold if r in SYMMETRIC}
    return [f"Will {clauses[i]}?" for i in order], sorted(gold)

def graph_scores(edges:list, gold:list, threshold:float=0.5) -> dict:
    "Precision, recall and F1 of a graph's edges (i, j, relation, confidence) at `threshold` against the gold (i, j, relation), overall and per relation"
    pred = {(h, t, r) for h, t, r, c in edges if c >= threshold}; gold = set(gold)
    out = {}
    for name in [None] + sorted({r for *_, r in gold | pred}):
        p, g = {e for e in pred if name in (None, e[2])}, {e for e in gold if name in (None, e[2])}
        tp = len(p & g)
        out[name or "all"] = {"p": tp / len(p) if p else float("nan"), "r": tp / len(g) if g else float("nan"), "f1": _f1(tp, len(p) - tp, len(g) - tp),
                              "edges": len(p), "gold": len(g)}
    return out
